function musicInit(){if(!S.music)S.music={songs:[],session:null,loop:false,chat:[]};S.music.songs=S.music.songs||[];S.music.chat=S.music.chat||[];if(S.music.totalSec==null)S.music.totalSec=0;if(S.music.distance==null)S.music.distance=1400;const normalize=typeof musicDiscColorNormalize==='function'?musicDiscColorNormalize:value=>{const raw=String(value||'').trim().toLowerCase();return ['black','white','blue','pink'].includes(raw)||/^#[0-9a-f]{6}$/.test(raw)?raw:'';},color=normalize(S.music.discColor);S.music.discColor=color||'black';if(color&&color.startsWith('#'))S.music.discCustomColor=color;S.music.discCustomColor=normalize(S.music.discCustomColor);if(!String(S.music.discCustomColor||'').startsWith('#'))S.music.discCustomColor='#8b5cf6';if(typeof musicDiscColorApply==='function')musicDiscColorApply(S.music.discColor);}
