function musicDiscColorDomApply(color){if(typeof document==='undefined')return;musicDiscColorApply(color);const page=document.querySelector('.music-premium');if(page){Array.from(page.classList).filter(x=>x.startsWith('music-disc-')).forEach(x=>page.classList.remove(x));page.classList.add('music-disc-'+color);}const vinyl=document.querySelector('.music-vinyl');if(vinyl&&color.startsWith('#')){const surface=musicDiscSurface();surface.style.split(';').filter(Boolean).forEach(row=>{const i=row.indexOf(':');if(i>0)vinyl.style.setProperty(row.slice(0,i),row.slice(i+1));});}}
