function musicDiscPickerHTML(discColor){const custom=discColor.startsWith('#'),customValue=custom?discColor:S.music.discCustomColor;return `<div class="music-disc-picker music-disc-picker-custom" role="group" aria-label="唱片颜色">${MUSIC_DISC_PRESETS.map(color=>`<button class="music-disc-choice${discColor===color?' on':''}" data-color="${color}" onclick="musicDiscColorSet('${color}')" aria-pressed="${discColor===color}"><i></i><span>${musicDiscColorName(color)}</span></button>`).join('')}<label class="music-disc-choice music-disc-custom-choice${custom?' on':''}" data-color="custom"><input type="color" value="${customValue}" aria-label="自定义唱片颜色" oninput="musicDiscColorInput(this.value)" onchange="musicDiscColorInput(this.value)"><i style="--custom-disc-preview:${customValue}"></i><span>自定义</span></label></div>`;}
