  if(APPDEFS.cozyhome&&!S.me._cozyThirdPageV1){for(const pg of clean){const i=pg.indexOf('cozyhome');if(i>=0)pg.splice(i,1);}clean[2].push('cozyhome');S.me._cozyThirdPageV1=1;}
